#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(0)
// The previous matcher is retained only as a behavioral/performance oracle.
static std::string referenceQuick(const moon::shortcuts::Bindings& bindings,const std::set<std::string>& held){using namespace moon::shortcuts;std::string best;std::size_t specificity=0;for(const auto& d:catalog()){if(d.id.size()<6||d.id.substr(d.id.size()-6)!=".quick")continue;for(const auto& binding:forId(bindings,d.id))if(blockedBy(bindings,d.id,binding).empty()&&heldPartsMatch(binding,held)){const auto n=std::size_t(1+std::count(binding.begin(),binding.end(),'+'));if(n>specificity){specificity=n;best=d.id;}}}return best;}
static void verifyQuickMatching(){using namespace moon::shortcuts;auto bindings=defaults();const std::array<std::set<std::string>,8> held={{{},{"Ctrl"},{"Alt"},{"Space"},{"Ctrl","Alt"},{"F8"},{"Ctrl","F8"},{"Shift","MouseMiddle"}}};auto verify=[&]{for(const auto& parts:held)CHECK(referenceQuick(bindings,parts)==quickToolMatch(bindings,parts,[](const auto&){return true;}));};verify();bindings["tool.hand.quick"]={"Ctrl","F8"};bindings["tool.eyedropper.quick"]={"Ctrl+Alt","F8"};bindings["undo"]={"F8"};verify();bindings["undo"].clear();verify();CHECK(!heldPartsMatch("",{}));CHECK(!heldPartsMatch("Ctrl",{}));int supportedCalls=0;CHECK(quickToolMatch(bindings,{},[&](const auto&){++supportedCalls;return true;}).empty());CHECK(supportedCalls==0);CHECK(quickToolMatch(bindings,{"Ctrl","Alt"},[](const auto&){return false;}).empty());
 bindings=defaults();std::size_t checksum=0;auto measure=[&](bool reference){const auto start=std::chrono::steady_clock::now();for(int i=0;i<2000;++i){const auto& parts=held[i%held.size()];checksum+=(reference?referenceQuick(bindings,parts):quickToolMatch(bindings,parts,[](const auto&){return true;})).size();}return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();};const auto before=measure(true),after=measure(false);std::cout<<"quick matcher 2000 events: reference_ms="<<before<<" optimized_ms="<<after<<" checksum="<<checksum<<'\n';}
int main(){verifyQuickMatching();using namespace moon::shortcuts;try{auto values=defaults();CHECK(matches(values,"undo","Ctrl+Z"));CHECK(matches(values,"relativeLuminance","Ctrl+Y"));CHECK(normalize(" shift + ctrl + a ")=="Ctrl+Shift+A");assign(values,"newLayer","Ctrl+Z");CHECK(forId(values,"undo").empty());reset(values,"undo");CHECK(forId(values,"newLayer")==forId(defaults(),"newLayer"));CHECK(!matches(values,"newLayer","Ctrl+Z"));assign(values,"undo","F8");assign(values,"undo","F8");CHECK(forId(values,"undo").size()==2);assign(values,"tool.pencil","F7");assign(values,"tool.eraser","F7");CHECK(matches(values,"tool.pencil","F7")&&matches(values,"tool.eraser","F7"));CHECK(mayShare("deselect","copyAnimationCel"));CHECK(!mayShare("tool.pencil.quick","tool.eraser.quick"));values["undo"].clear();assign(values,"tool.pencil","MouseLeft");CHECK(decode(encode(values))==values);auto imported=decode(R"({"undo":[],"temporaryEyedropper":"Alt"})");CHECK(forId(imported,"undo").empty());CHECK(forId(imported,"tool.eyedropper.quick")==std::vector<std::string>{"Alt"});bool rejected=false;try{decode(R"({"undo":"Escape"})");}catch(...){rejected=true;}CHECK(rejected);values=defaults();values["undo"]={"F8","F9"};values["redo"]={"F8","F10"};CHECK(!blockedBy(values,"redo","F8").empty());CHECK(blockedBy(values,"redo","F10").empty());CHECK(heldPartsMatch("Ctrl+F8",{"Ctrl","Alt","F8"}));CHECK(!heldPartsMatch("Ctrl+F8",{"Ctrl"}));CHECK(!heldPartsMatch("WheelUp",{"WheelUp"}));CHECK(recordableBinding("undo","MouseRight"));CHECK(recordableBinding("tool.hand.quick","F8"));CHECK(!recordableBinding("tool.hand.quick","MouseLeft"));values=defaults();values["tool.hand.quick"]={"Ctrl"};values["tool.eyedropper.quick"]={"Ctrl+Alt"};CHECK(quickToolMatch(values,{"Ctrl","Alt"},[](const auto&){return true;})=="tool.eyedropper.quick");std::cout<<"shortcuts tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
